SELECT store_sales.product_id, CASE WHEN store_sales.units >= 42 THEN 'high' WHEN store_sales.units >= 9 THEN 'mid' ELSE 'low' END AS units_bucket, MAX(inventory.quantity) AS max_quantity FROM inventory INNER JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE inventory.last_restock >= '2023-06-01' GROUP BY store_sales.product_id, CASE WHEN store_sales.units >= 42 THEN 'high' WHEN store_sales.units >= 9 THEN 'mid' ELSE 'low' END;
